int16_t barrett_reduce(int16_t a) {
  // The reference computes a modulo 3329 centered in [-1664, 1664].
  // Its rounded reciprocal selects the nearest quotient for every int16_t.
  // C remainder has magnitude below 3329; one correction centers it.
  // Wide arithmetic handles both int16_t endpoints without overflow.
  int32_t r = (int32_t)a % 3329;
  if (r > 1664)
    r -= 3329;
  else if (r < -1664)
    r += 3329;
  return (int16_t)r;
}

int16_t barrett_reduce(int16_t a) {
  // Truncating division gives a remainder with magnitude below 3329.
  // Comparison flags correct either noncentered tail by one modulus.
  // The centered representative matches the reference for every input.
  // All intermediates fit int32_t, including at both int16_t endpoints.
  int32_t x = a;
  int32_t q = x / 3329;
  int32_t r = x - q * 3329;
  r += 3329 * ((r < -1664) - (r > 1664));
  return (int16_t)r;
}

int16_t barrett_reduce(int16_t a) {
  // Add ten moduli and 1664 to make the dividend strictly positive.
  // Its remainder minus 1664 is congruent to a and lies in the centered range.
  // Uniqueness of that representative establishes equality to the reference.
  // The biased dividend ranges from 2186 to 67721, so endpoints are safe.
  int32_t x = (int32_t)a + 34954;
  return (int16_t)(x % 3329 - 1664);
}

int16_t barrett_reduce(int16_t a) {
  // Positive biased division computes floor((a + 1664) / 3329) plus ten.
  // Subtracting ten gives the quotient selecting the centered remainder.
  // This equals the reference quotient throughout the int16_t domain.
  // Wide products avoid narrow overflow even when the quotient is ten.
  int32_t x = a;
  int32_t q = (x + 34954) / 3329 - 10;
  return (int16_t)(x - q * 3329);
}

int16_t barrett_reduce(int16_t a) {
  // Reduce the magnitude, center it, and restore the original sign.
  // Centered reduction is odd because the odd modulus permits no halfway tie.
  // Thus this gives the same centered residue as the reference.
  // Widening before negation safely handles a equal to -32768.
  int32_t x = a;
  int32_t magnitude = x < 0 ? -x : x;
  int32_t r = magnitude % 3329;
  if (r > 1664)
    r -= 3329;
  return (int16_t)(x < 0 ? -r : r);
}

int16_t barrett_reduce(int16_t a) {
  // Repeatedly add or subtract the modulus until the value is centered.
  // Each step preserves congruence and moves toward [-1664, 1664].
  // The unique centered result is exactly the reference result.
  // At most ten iterations are needed, including at either input endpoint.
  int32_t r = a;
  while (r > 1664)
    r -= 3329;
  while (r < -1664)
    r += 3329;
  return (int16_t)r;
}

int16_t barrett_reduce(int16_t a) {
  // Bias into [2186, 67721], then reduce using descending binary multiples.
  // Each conditional subtraction leaves less than the multiple just tested.
  // The final value is the nonnegative remainder modulo 3329.
  // Subtracting 1664 gives the reference's centered residue, endpoints included.
  int32_t r = (int32_t)a + 34954;
  if (r >= 53264)
    r -= 53264;
  if (r >= 26632)
    r -= 26632;
  if (r >= 13316)
    r -= 13316;
  if (r >= 6658)
    r -= 6658;
  if (r >= 3329)
    r -= 3329;
  return (int16_t)(r - 1664);
}

int16_t barrett_reduce(int16_t a) {
  // Process all seventeen bits of the positive biased input by long division.
  // Each step doubles a remainder and adds a bit, needing at most one subtraction.
  // The invariant keeps r in [0, 3328] with no overflowing intermediates.
  // Removing the 1664 bias yields the reference result for all int16_t inputs.
  int32_t x = (int32_t)a + 34954;
  int32_t r = 0;
  int bit;
  for (bit = 16; bit >= 0; --bit) {
    r = r * 2 + ((x >> bit) & 1);
    if (r >= 3329)
      r -= 3329;
  }
  return (int16_t)(r - 1664);
}

int16_t barrett_reduce(int16_t a) {
  // Use the reference reciprocal, 20159, but replace its arithmetic shift.
  // Division truncates toward zero; correcting negative remainders gives floor.
  // This reproduces the reference's rounded quotient without a negative shift.
  // Wide subtraction directly produces the centered result at both endpoints.
  int32_t x = (int32_t)20159 * a + 33554432;
  int32_t q = x / 67108864;
  if (x % 67108864 < 0)
    --q;
  return (int16_t)((int32_t)a - q * 3329);
}

int16_t barrett_reduce(int16_t a) {
  // Apply the rounded reciprocal to the magnitude and restore the result's sign.
  // Since 20159 * 3329 equals 67108864 + 447, quotient error is below 0.000066.
  // This is below the minimum distance to a rounding tie, 1 / 6658.
  // Thus the quotient is nearest and centered reduction is odd for every input.
  // Widening before negation and multiplication also covers a equal to -32768.
  int32_t x = a;
  int32_t magnitude = x < 0 ? -x : x;
  int32_t q = (20159 * magnitude + 33554432) / 67108864;
  int32_t r = magnitude - q * 3329;
  return (int16_t)(x < 0 ? -r : r);
}
